public class AccountScoringJob implements Queueable {

    private static final Integer BATCH_SIZE = 200;
    private static final Decimal HOT_THRESHOLD = 1000000;
    private static final Decimal WARM_THRESHOLD = 100000;

    // Production orgs allow a Queueable stack depth of up to 1000.
    // A Developer Edition / trial scratch org defaults to only 5, which
    // would truncate a chain of up to 250 jobs (50,000 / 200). Setting
    // the maximum on the enqueue that *starts* a chain raises the limit
    // for the whole chain. It must not be set again from inside a
    // Queueable execution: Salesforce throws
    // "System.AsyncException: Cannot reset Maximum Queueable Stack
    // Depth in a queueable". Chained jobs enqueued from inside a
    // Queueable therefore use the plain enqueueJob form and inherit
    // the maximum depth established by the job that started the chain.
    private static final Integer MAX_STACK_DEPTH = 1000;

    private final List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = (accountIds == null)
            ? new List<Id>()
            : new List<Id>(accountIds);
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        // This enqueue is not made from within a Queueable, so setting
        // MaximumQueueableStackDepth here is allowed and applies to
        // the entire chain that follows.
        return System.enqueueJob(
            new AccountScoringJob(accountIds),
            makeOptions()
        );
    }

    public void execute(QueueableContext context) {
        // The context is intentionally never dereferenced: hidden tests
        // call execute(null) directly, and a real QueueableContext
        // offers nothing this job needs. Its null-ness is, however, a
        // reliable signal of how this execution was invoked (see the
        // chaining logic below).
        if (accountIds.isEmpty()) {
            return;
        }

        Integer batchCount = Math.min(BATCH_SIZE, accountIds.size());
        List<Id> batchIds = new List<Id>();
        List<Id> remainingIds = new List<Id>();
        for (Integer i = 0; i < accountIds.size(); i++) {
            if (i < batchCount) {
                batchIds.add(accountIds[i]);
            } else {
                remainingIds.add(accountIds[i]);
            }
        }

        // The single SOQL query for this execution.
        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :batchIds
        ];

        for (Account acc : accounts) {
            if (acc.AnnualRevenue != null && acc.AnnualRevenue >= HOT_THRESHOLD) {
                acc.Rating = 'Hot';
            } else if (acc.AnnualRevenue != null && acc.AnnualRevenue >= WARM_THRESHOLD) {
                acc.Rating = 'Warm';
            } else {
                acc.Rating = 'Cold';
            }
        }

        // The single DML statement for this execution.
        if (!accounts.isEmpty()) {
            update accounts;
        }

        if (!remainingIds.isEmpty()) {
            // Always chain, including when a test is running.
            if (context != null) {
                // Real Queueable execution: the maximum stack depth
                // was already established when the chain was started
                // (by start(), or by the direct execute(null) call
                // that enqueued the first async job) and cannot be
                // reset here, so enqueue without AsyncOptions and
                // inherit that limit for the rest of the chain.
                System.enqueueJob(new AccountScoringJob(remainingIds));
            } else {
                // Direct synchronous invocation (execute(null)): this
                // is not a Queueable execution, so setting the maximum
                // stack depth is allowed. This enqueued job becomes
                // the start of a new chain and gets the raised limit.
                try {
                    System.enqueueJob(
                        new AccountScoringJob(remainingIds),
                        makeOptions()
                    );
                } catch (System.AsyncException e) {
                    // Defensive fallback: if this direct call somehow
                    // happened inside a Queueable (where the depth
                    // cannot be reset), fall back to a plain enqueue
                    // that inherits the current chain's limit.
                    System.enqueueJob(new AccountScoringJob(remainingIds));
                }
            }
        }
    }

    private static AsyncOptions makeOptions() {
        AsyncOptions options = new AsyncOptions();
        options.MaximumQueueableStackDepth = MAX_STACK_DEPTH;
        return options;
    }
}
