@IsTest
private class OpportunitiesServiceTest {

    private class TestContext {
        fflib_ApexMocks mocks;
        IOpportunities mockDomain;
        IOpportunitiesSelector mockSelector;
        fflib_ISObjectUnitOfWork mockUow;
    }

    private static TestContext setupMocks(List<Opportunity> recordsToReturn) {
        TestContext ctx = new TestContext();
        ctx.mocks = new fflib_ApexMocks();
        ctx.mockUow = (fflib_ISObjectUnitOfWork) ctx.mocks.mock(fflib_ISObjectUnitOfWork.class);
        ctx.mockSelector = (IOpportunitiesSelector) ctx.mocks.mock(IOpportunitiesSelector.class);
        ctx.mockDomain = (IOpportunities) ctx.mocks.mock(IOpportunities.class);

        ctx.mocks.startStubbing();
        // fflib factories key mocks by sObjectType(); this must be stubbed
        // before setMock() is called, otherwise the mocks are registered
        // under a null key and the factories fall back to real instances.
        ctx.mocks.when(ctx.mockSelector.sObjectType()).thenReturn(Opportunity.SObjectType);
        ctx.mocks.when(ctx.mockDomain.sObjectType()).thenReturn(Opportunity.SObjectType);
        if (recordsToReturn != null) {
            ctx.mocks.when(
                ctx.mockSelector.selectById((Set<Id>) fflib_Match.anyObject())
            ).thenReturn(recordsToReturn);
        }
        ctx.mocks.stopStubbing();

        Application.UnitOfWork.setMock(ctx.mockUow);
        Application.Selector.setMock((fflib_ISObjectSelector) ctx.mockSelector);
        Application.Domain.setMock((fflib_ISObjectDomain) ctx.mockDomain);
        return ctx;
    }

    private static List<Opportunity> makeOpportunities(Set<Id> opportunityIds) {
        List<Opportunity> records = new List<Opportunity>();
        for (Id opportunityId : opportunityIds) {
            records.add(new Opportunity(Id = opportunityId, Amount = 100));
        }
        return records;
    }

    private static void verifyNothingAppliedOrCommitted(TestContext ctx) {
        ((IOpportunitiesSelector) ctx.mocks.verify(ctx.mockSelector, fflib_ApexMocks.NEVER))
            .selectById((Set<Id>) fflib_Match.anyObject());
        ((IOpportunities) ctx.mocks.verify(ctx.mockDomain, fflib_ApexMocks.NEVER))
            .applyDiscount(
                (Decimal) fflib_Match.anyObject(),
                (fflib_ISObjectUnitOfWork) fflib_Match.anyObject()
            );
        ((fflib_ISObjectUnitOfWork) ctx.mocks.verify(ctx.mockUow, fflib_ApexMocks.NEVER))
            .commitWork();
    }

    private static void verifyDomainAndUowNotUsed(TestContext ctx) {
        ((IOpportunities) ctx.mocks.verify(ctx.mockDomain, fflib_ApexMocks.NEVER))
            .applyDiscount(
                (Decimal) fflib_Match.anyObject(),
                (fflib_ISObjectUnitOfWork) fflib_Match.anyObject()
            );
        ((fflib_ISObjectUnitOfWork) ctx.mocks.verify(ctx.mockUow, fflib_ApexMocks.NEVER))
            .commitWork();
    }

    private static void assertInvalidDiscount(Decimal discountPercentage) {
        Set<Id> opportunityIds = new Set<Id>{
            fflib_IDGenerator.generate(Opportunity.SObjectType),
            fflib_IDGenerator.generate(Opportunity.SObjectType)
        };
        TestContext ctx = setupMocks(makeOpportunities(opportunityIds));

        Boolean thrown = false;
        try {
            OpportunitiesService.applyDiscounts(opportunityIds, discountPercentage);
        } catch (OpportunitiesService.OpportunitiesServiceException e) {
            thrown = true;
            Assert.areEqual(
                'Discount must be greater than 0 and at most 50 percent.',
                e.getMessage(),
                'Unexpected exception message'
            );
        }
        Assert.isTrue(thrown, 'Expected OpportunitiesServiceException for discount: ' + discountPercentage);

        verifyDomainAndUowNotUsed(ctx);
    }

    private static void assertSuccessfulApply(Decimal discountPercentage) {
        Set<Id> opportunityIds = new Set<Id>{
            fflib_IDGenerator.generate(Opportunity.SObjectType),
            fflib_IDGenerator.generate(Opportunity.SObjectType)
        };
        List<Opportunity> records = makeOpportunities(opportunityIds);
        TestContext ctx = setupMocks(records);

        OpportunitiesService.applyDiscounts(opportunityIds, discountPercentage);

        // Selector used once with the exact ids.
        ((IOpportunitiesSelector) ctx.mocks.verify(ctx.mockSelector, 1))
            .selectById(opportunityIds);

        // Domain applyDiscount called exactly once, percentage unchanged, with the injected UoW.
        ((IOpportunities) ctx.mocks.verify(ctx.mockDomain, 1))
            .applyDiscount(discountPercentage, ctx.mockUow);

        // Unit of work committed exactly once.
        ((fflib_ISObjectUnitOfWork) ctx.mocks.verify(ctx.mockUow, 1))
            .commitWork();

        // commitWork() must happen only after applyDiscount().
        fflib_InOrder inOrder = (fflib_InOrder) ctx.mocks.inOrder(
            new List<Object>{ ctx.mockDomain, ctx.mockUow }
        );
        ((IOpportunities) inOrder.verify(ctx.mockDomain))
            .applyDiscount(discountPercentage, ctx.mockUow);
        ((fflib_ISObjectUnitOfWork) inOrder.verify(ctx.mockUow))
            .commitWork();
    }

    private static void assertNoWorkForIds(Set<Id> opportunityIds) {
        Set<Id> stubIds = new Set<Id>{
