        assertInvalidDiscount(0);
    }

    @IsTest
    static void applyDiscounts_NegativeDiscount_ThrowsAndDoesNotUseDomainOrUnitOfWork() {
        assertInvalidDiscount(-5);
    }

    @IsTest
    static void applyDiscounts_DiscountAboveFifty_ThrowsAndDoesNotUseDomainOrUnitOfWork() {
        assertInvalidDiscount(50.01);
    }

    @IsTest
    static void applyDiscounts_NullIds_NothingAppliedOrCommitted() {
        assertNoWorkForIds(null);
    }

