public class OpportunityWinService {
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities = OpportunitiesSelector.newInstance()
            .selectById(opportunityIds);

        List<Opportunity> opportunitiesToClose = new List<Opportunity>();
        for (Opportunity opportunity : opportunities) {
            if (opportunity.StageName != 'Closed Won') {
                opportunitiesToClose.add(opportunity);
            }
        }

        if (opportunitiesToClose.isEmpty()) {
            return 0;
        }

        fflib_ISObjectUnitOfWork unitOfWork = Application.UnitOfWork.newInstance();

        List<SObject> eventsToPublish = new List<SObject>();
        for (Opportunity opportunity : opportunitiesToClose) {
            opportunity.StageName = 'Closed Won';
            opportunity.CloseDate = Date.today();
            unitOfWork.registerDirty(opportunity);

            eventsToPublish.add(
                new Deal_Won__e(
                    Opportunity_Id__c = String.valueOf(opportunity.Id),
                    Amount__c = opportunity.Amount
                )
            );
        }

        // Deal_Won__e has Publish Immediately behaviour, so it must not be
        // published via registerNew / registerPublishBeforeTransaction in
        // the same transaction as the Opportunity updates.
        // registerPublishAfterTransaction (List<SObject> overload in this
        // version of fflib) publishes only after the unit of work has
        // committed successfully. If commitWork() fails, the exception
        // propagates and no event is published.
        unitOfWork.registerPublishAfterTransaction(eventsToPublish);

        unitOfWork.commitWork();

        return opportunitiesToClose.size();
    }
}
